  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\nmodel Usuario {\n  id              Int             @id @default(autoincrement())\n  nome            String          @db.VarChar(100)\n  email           String          @unique @db.VarChar(150)\n  senha           String          @db.VarChar(255)\n  avatar          String?         @db.LongText\n  nivelHabilidade NivelHabilidade @default(INICIANTE)\n  criadoEm        DateTime        @default(now())\n  atualizadoEm    DateTime        @updatedAt\n\n  perfil      PerfilAlimentar?\n  inventario  Inventario[]\n  receitas    Receita[]\n  postagens   Postagem[]\n  comentarios Comentario[]\n  favoritos   Favorito[]\n  geracoes    ReceitaGeracao[]\n\n  @@map(\"usuarios\")\n}\n\nenum NivelHabilidade {\n  INICIANTE\n  INTERMEDIARIO\n  AVANCADO\n}\n\n// ─────────────────────────────────────────\n// Perfil Alimentar\n// ─────────────────────────────────────────\n\nmodel PerfilAlimentar {\n  id           Int       @id @default(autoincrement())\n  usuarioId    Int       @unique\n  tipoDieta    TipoDieta @default(ONIVORO)\n  criadoEm     DateTime  @default(now())\n  atualizadoEm DateTime  @updatedAt\n\n  usuario    Usuario              @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  restricoes RestricaoAlimentar[]\n\n  @@map(\"perfis_alimentares\")\n}\n\nenum TipoDieta {\n  ONIVORO\n  VEGETARIANO\n  VEGANO\n  PESCATARIANO\n  CETOGENICO\n  OUTRO\n}\n\n// Uma linha por restrição — permite múltiplas restrições por usuário\nmodel RestricaoAlimentar {\n  id       Int    @id @default(autoincrement())\n  perfilId Int\n  tipo     String @db.VarChar(100) // ex: \"sem glúten\", \"sem lactose\"\n\n  perfil PerfilAlimentar @relation(fields: [perfilId], references: [id], onDelete: Cascade)\n\n  @@map(\"restricoes_alimentares\")\n}\n\n// ─────────────────────────────────────────\n// Ingredientes (tabela normalizada)\n// ─────────────────────────────────────────\n\nmodel Ingrediente {\n  id                  Int     @id @default(autoincrement())\n  nome                String  @unique @db.VarChar(150)\n  categoria           String  @db.VarChar(100) // ex: \"laticínios\", \"grãos\", \"legumes\"\n  classificacaoStatus String  @default(\"NAO_VERIFICADO\") @db.VarChar(30)\n  dietasPermitidas    String? @db.Text\n  restricoes          String? @db.Text\n\n  inventarios         Inventario[]\n  receitaIngredientes ReceitaIngrediente[]\n\n  @@map(\"ingredientes\")\n}\n\n// ─────────────────────────────────────────\n// Inventário do usuário\n// ─────────────────────────────────────────\n\nmodel Inventario {\n  id            Int    @id @default(autoincrement())\n  usuarioId     Int\n  ingredienteId Int\n  quantidade    Float\n  unidade       String @db.VarChar(30) // ex: \"g\", \"ml\", \"unidade\", \"xícara\"\n\n  usuario     Usuario     @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  ingrediente Ingrediente @relation(fields: [ingredienteId], references: [id])\n\n  @@unique([usuarioId, ingredienteId])\n  @@map(\"inventario\")\n}\n\n// ─────────────────────────────────────────\n// Receitas\n// ─────────────────────────────────────────\n\nmodel Receita {\n  id            Int      @id @default(autoincrement())\n  usuarioId     Int\n  titulo        String   @db.VarChar(200)\n  modoPreparo   String   @db.Text\n  tempoEstimado Int // em minutos\n  porcoes       Int      @default(1)\n  imagem        String?  @db.LongText\n  publica       Boolean  @default(true)\n  geradaPorIA   Boolean  @default(false) // flag para quando a IA for integrada\n  criadaEm      DateTime @default(now())\n  atualizadaEm  DateTime @updatedAt\n\n  usuario      Usuario              @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  ingredientes ReceitaIngrediente[]\n  postagens    Postagem[]\n  comentarios  Comentario[]\n  favoritos    Favorito[]\n\n  @@map(\"receitas\")\n}\n\nmodel Favorito {\n  id        Int      @id @default(autoincrement())\n  usuarioId Int\n  receitaId Int\n  criadoEm  DateTime @default(now())\n\n  usuario Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  receita Receita @relation(fields: [receitaId], references: [id], onDelete: Cascade)\n\n  @@unique([usuarioId, receitaId])\n  @@map(\"favoritos\")\n}\n\nmodel ReceitaGeracao {\n  id               Int       @id @default(autoincrement())\n  usuarioId        Int\n  chaveCache       String    @db.VarChar(191)\n  modelo           String    @db.VarChar(100)\n  status           String    @db.VarChar(30)\n  payload          Json?\n  consumo          Json?\n  erroCodigo       String?   @db.VarChar(50)\n  receitaId        Int?\n  cacheExpiraEm    DateTime?\n  rascunhoExpiraEm DateTime?\n  criadaEm         DateTime  @default(now())\n  finalizadaEm     DateTime?\n  duracaoMs        Int?\n  reservaExpiraEm  DateTime?\n\n  usuario Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  @@index([usuarioId, criadaEm])\n  @@index([usuarioId, chaveCache])\n  @@index([receitaId])\n  @@index([criadaEm])\n  @@map(\"receita_geracoes\")\n}\n\nmodel IaControle {\n  id Int @id\n\n  @@map(\"ia_controle\")\n}\n\n// ─────────────────────────────────────────\n// Receita ↔ Ingredientes (N:N)\n// ─────────────────────────────────────────\n\nmodel ReceitaIngrediente {\n  receitaId     Int\n  ingredienteId Int\n  quantidade    Float\n  unidade       String  @db.VarChar(30)\n  opcional      Boolean @default(false)\n\n  receita     Receita     @relation(fields: [receitaId], references: [id], onDelete: Cascade)\n  ingrediente Ingrediente @relation(fields: [ingredienteId], references: [id])\n\n  @@id([receitaId, ingredienteId])\n  @@map(\"receita_ingredientes\")\n}\n\nmodel Comentario {\n  id           Int      @id @default(autoincrement())\n  receitaId    Int\n  usuarioId    Int\n  respostaDeId Int?\n  texto        String   @db.Text\n  criadoEm     DateTime @default(now())\n\n  receita    Receita      @relation(fields: [receitaId], references: [id], onDelete: Cascade)\n  usuario    Usuario      @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  respostaDe Comentario?  @relation(\"RespostasComentario\", fields: [respostaDeId], references: [id], onDelete: Cascade)\n  respostas  Comentario[] @relation(\"RespostasComentario\")\n\n  @@index([receitaId, criadoEm])\n  @@map(\"comentarios\")\n}\n\n// ─────────────────────────────────────────\n// Postagens da comunidade\n// ─────────────────────────────────────────\n\nmodel Postagem {\n  id          Int      @id @default(autoincrement())\n  usuarioId   Int\n  receitaId   Int?\n  imagemPrato String?  @db.VarChar(500) // URL da imagem\n  comentario  String?  @db.Text\n  criadaEm    DateTime @default(now())\n\n  usuario Usuario  @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  receita Receita? @relation(fields: [receitaId], references: [id], onDelete: SetNull)\n\n  @@map(\"postagens\")\n}\n"
